class stringx
{
public:
  static const int npos = -1;
  int find(const char *) const;
};

class entity
{
public:
  stringx get_parsed_name();
};

class beach_object
{
public:
  virtual void jumped_over(entity *ent);
};

class beach
{
public:
  beach_object *find_object(entity *ent) const;
};

extern beach *g_beach_ptr;

enum EventType
{
  SS_PIER_CHEER = 51
};

class SoundScriptManager
{
public:
  static SoundScriptManager *inst();
  int playEvent(EventType type, entity *ent = 0, float fadeInTime = 0);
};

class kellyslater_controller
{
  enum { MAX_JUMP_ENT = 3 };
  entity *owner;
  entity *jumped_entities[MAX_JUMP_ENT];
  int num_jumped__entities;

public:
  void SetJumpedEntity(entity *ent);
};

void kellyslater_controller::SetJumpedEntity (entity *ent)
{
	bool exists = false;

	if (!ent || (num_jumped__entities > 0 && ent == jumped_entities[num_jumped__entities-1]))
		return;

	g_beach_ptr->find_object (ent)->jumped_over (owner);

	if (num_jumped__entities < MAX_JUMP_ENT)
	{
		// Toby change: only add this entity if it has not been added yet.
		for (int i = 0; i < num_jumped__entities; i++)
		{
			if (jumped_entities[i] == ent)
				exists = true;
		}

		if (!exists)
		{
			jumped_entities[num_jumped__entities++] = ent;
			if (ent->get_parsed_name().find ("sebastian_pier") != stringx::npos )
			{
				SoundScriptManager::inst()->playEvent(SS_PIER_CHEER, ent);
			}
		}
	}
}
